package com.gaurav.datasave;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity{LinearLayout list; android.content.SharedPreferences sp; public void onCreate(Bundle b){super.onCreate(b);sp=getSharedPreferences("shops",0);draw();} TextView t(String x,int s){TextView v=new TextView(this);v.setText(x);v.setTextSize(s);v.setPadding(20,14,20,14);return v;} void draw(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);root.addView(t("Gaurav Data Save",28));EditText n=new EditText(this);n.setHint("Shop / Party name");root.addView(n);EditText p=new EditText(this);p.setHint("Phone");p.setInputType(3);root.addView(p);EditText m=new EditText(this);m.setHint("Google Maps location / link");root.addView(m);EditText a=new EditText(this);a.setHint("Area");root.addView(a);EditText c=new EditText(this);c.setHint("Category");root.addView(c);EditText no=new EditText(this);no.setHint("Note");root.addView(no);Button save=new Button(this);save.setText("SAVE LOCATION");root.addView(save);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);save.setOnClickListener(v->{if(n.getText().toString().trim().isEmpty()){Toast.makeText(this,"Shop name required",0).show();return;}try{JSONArray ar=new JSONArray(sp.getString("data","[]"));JSONObject o=new JSONObject();o.put("n",n.getText());o.put("p",p.getText());o.put("m",m.getText());o.put("a",a.getText());o.put("c",c.getText());o.put("no",no.getText());ar.put(o);sp.edit().putString("data",ar.toString()).apply();draw();}catch(Exception e){}});render();sc.addView(root);setContentView(sc);} void render(){try{JSONArray ar=new JSONArray(sp.getString("data","[]"));for(int i=ar.length()-1;i>=0;i--){JSONObject o=ar.getJSONObject(i);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(10,18,10,18);card.addView(t(o.optString("n")+"\n"+o.optString("p")+"  "+o.optString("a")+"\n"+o.optString("c")+"\n"+o.optString("no"),18));LinearLayout row=new LinearLayout(this);String ph=o.optString("p"),mp=o.optString("m");Button call=new Button(this);call.setText("Call");call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+ph))));row.addView(call);Button wa=new Button(this);wa.setText("WhatsApp");wa.setOnClickListener(v->{String q=ph.replaceAll("\\D","");if(q.length()==10)q="91"+q;startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+q)));});row.addView(wa);Button map=new Button(this);map.setText("Map");map.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(mp)));}catch(Exception e){}});row.addView(map);card.addView(row);list.addView(card);}}catch(Exception e){}}}